import React,{useEffect,useState}from 'react';
import {createRoot}from 'react-dom/client';
import {BrowserRouter,Routes,Route,Link,useNavigate,useParams,Navigate}from 'react-router-dom';
import {MapContainer,TileLayer,Marker,useMapEvents}from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import api from './api/client';
import {AuthProvider,useAuth} from './auth/AuthContext';
import './style.css';
import './marketplace.css';

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({iconRetinaUrl:'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',iconUrl:'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',shadowUrl:'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png'});
const money=n=>n==null?'Not specified':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const AVAILABILITY_STALE_AFTER_MS=7*24*60*60*1000;
const problem=e=>e?.response?.data?.message||'Unable to complete that action. Please try again.';
const fallback='https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=1200&q=85';
const imageFileToDataUrl=file=>new Promise((resolve,reject)=>{if(file.size>8*1024*1024){reject(new Error('Each image must be smaller than 8 MB.'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read this image.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('This file is not a valid image.'));image.onload=()=>{const scale=Math.min(1,960/image.width,960/image.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(!blob||blob.size>200000){reject(new Error('Image is too large after compression. Choose a smaller photo.'));return}const output=new FileReader();output.onerror=()=>reject(new Error('Could not process this image.'));output.onload=()=>resolve(output.result);output.readAsDataURL(blob)},'image/jpeg',.62)};image.src=reader.result};reader.readAsDataURL(file)});

function Logo(){return <Link className="logo" to="/"><span className="logo-mark">⌂</span><span>Hostel<span>Dekho</span></span></Link>}
function Footer(){return <footer className="site-footer"><Logo/><span>Find a student stay that feels right.</span><a href="mailto:hello@hosteldekho.com">Contact</a><small>© 2026 HostelDekho</small></footer>}
function Nav(){const nav=useNavigate(),{isAuthenticated,signOut}=useAuth();return <header className="site-nav"><Logo/><nav><Link to="/#explore">Explore hostels</Link>{isAuthenticated?<><Link to="/manager">My dashboard</Link><button className="nav-button" onClick={()=>{signOut();nav('/')}}>Log out</button></>:<Link className="nav-button" to="/login">List your hostel</Link>}</nav></header>}
function Chips({value,onChange}){return <div className="chips">{[['','All'],['MALE','Boys'],['FEMALE','Girls'],['CO_ED','Mixed']].map(([key,label])=><button type="button" className={value===key?'selected':''} onClick={()=>onChange(key)} key={label}>{label}</button>)}</div>}
function Card({hostel,college}){const image=hostel.imageUrls?.[0]||fallback,detailPath=`/hostels/${hostel.id}${college?`?college=${encodeURIComponent(college)}`:''}`;return <article className="hostel-card"><Link to={detailPath} className="card-image"><img src={image} alt={hostel.name} onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=fallback}}/><span className="price-badge">{money(hostel.startingPricePerMonth)} <small>/ mo</small></span><span className="gallery-dot">● ● ●</span></Link><div className="card-body"><h2>{hostel.name}</h2><p className="muted">{hostel.genderType==='CO_ED'?'Co-ed hostel':hostel.genderType==='MALE'?"Men's hostel":"Women's hostel"}</p><p className="location">⌖ {hostel.locality}, Visakhapatnam</p><div className="feature-row">{hostel.roomTypes?.map(t=><span key={t}>{t==='AC'?'❄ AC':'◌ Non-AC'}</span>)}{hostel.coLiving&&<span>Co-living</span>}</div><div className="card-footer"><span className={hostel.vacantBeds?'available':'full'}>{hostel.vacantBeds?`${hostel.vacantBeds} beds left`:'Full'}</span>{hostel.distanceKm!=null&&<span className="distance-chip">{hostel.distanceKm} km from {college||'college'}</span>}<Link to={detailPath}>View →</Link></div></div></article>}
function CollegeAutocomplete(){const[colleges,setColleges]=useState([]),[query,setQuery]=useState(''),[loading,setLoading]=useState(true),[error,setError]=useState('');useEffect(()=>{api.get('/colleges').then(r=>setColleges(r.data)).catch(e=>setError(problem(e))).finally(()=>setLoading(false))},[]);const matches=colleges.filter(c=>`${c.name} ${c.locality} ${c.city}`.toLowerCase().includes(query.toLowerCase())).slice(0,6);return <section className="college-autocomplete"><label htmlFor="college-autocomplete-input">Find hostels by college</label><input id="college-autocomplete-input" value={query} placeholder="Search a college or locality" onChange={e=>setQuery(e.target.value)}/>{loading&&<small>Loading colleges…</small>}{error&&<small className="notice error">{error}</small>}{query&&matches.length>0&&<div className="college-suggestions" role="listbox">{matches.map(c=><Link role="option" key={c.id} to={`/colleges/${c.slug}`}><b>{c.name}</b><span>{c.locality}, {c.city}</span></Link>)}</div>}{query&&!loading&&!error&&!matches.length&&<small>No colleges found.</small>}</section>}
function FoodSearchControls(){const[foodIncluded,setFoodIncluded]=useState(''),[foodType,setFoodType]=useState('');useEffect(()=>{const reset=()=>{setFoodIncluded('');setFoodType('')};window.addEventListener('hostel-food-reset',reset);return()=>window.removeEventListener('hostel-food-reset',reset)},[]);const update=(included,type)=>{setFoodIncluded(included);setFoodType(type);window.dispatchEvent(new CustomEvent('hostel-food-filter',{detail:{foodIncluded:included,foodType:type}}))};return <section className="food-search-controls"><b>Food</b><label>Mess inclusion<select aria-label="Food included filter" value={foodIncluded} onChange={e=>update(e.target.value,foodType)}><option value="">Any</option><option value="true">Included in rent</option><option value="false">Paid separately</option></select></label><label>Food type<select aria-label="Food type filter" value={foodType} onChange={e=>update(foodIncluded,e.target.value)}><option value="">Any type</option><option value="VEG">Veg</option><option value="NON_VEG">Non-veg</option><option value="BOTH">Veg and non-veg</option><option value="NONE">No food service</option></select></label></section>}
function Home({initialCollegeId='',fixedCollegeName=''}){
 const [colleges,setColleges]=useState([]),[items,setItems]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState('');
 const [filters,setFilters]=useState({collegeId:initialCollegeId,gender:'',acType:'',minPrice:'',maxPrice:'',onlyVacant:true,coLiving:'',foodIncluded:'',foodType:''}),[sort,setSort]=useState('recommended'),[mobileFilters,setMobileFilters]=useState(false);
 useEffect(()=>{api.get('/colleges').then(r=>setColleges(r.data)).catch(e=>setError(problem(e)))},[]);
 const search=async event=>{event?.preventDefault();setLoading(true);setError('');try{const params=Object.fromEntries(Object.entries(filters).filter(([,v])=>v!==''&&v!==undefined));setItems((await api.get('/hostels',{params})).data)}catch(e){setError(problem(e))}finally{setLoading(false)}};
 useEffect(()=>{search()},[filters]);
 useEffect(()=>{const onFood=e=>setFilters(current=>({...current,...e.detail}));window.addEventListener('hostel-food-filter',onFood);return()=>window.removeEventListener('hostel-food-filter',onFood)},[]);
 const clear=()=>{window.dispatchEvent(new Event('hostel-food-reset'));setFilters({collegeId:initialCollegeId,gender:'',acType:'',minPrice:'',maxPrice:'',onlyVacant:true,coLiving:'',foodIncluded:'',foodType:''})};
 const selectedCollege=colleges.find(c=>String(c.id)===String(filters.collegeId));
 const sortedItems=[...items].sort((a,b)=>sort==='price-low'?a.startingPricePerMonth-b.startingPricePerMonth:sort==='price-high'?b.startingPricePerMonth-a.startingPricePerMonth:sort==='vacancies'?b.vacantBeds-a.vacantBeds:sort==='distance'?(a.distanceKm??Infinity)-(b.distanceKm??Infinity):0);
 return <main className="discovery-page">
  {!fixedCollegeName&&<><section className="travel-hero"><div className="hero-cloud cloud-one"/><div className="hero-cloud cloud-two"/><div className="hero-copy"><p className="eyebrow">STUDENT STAYS, MADE SIMPLE</p><h1>Find a place that<br/>feels like <em>home.</em></h1><p>Verified student hostels near the college you choose.</p><form className="hero-search" onSubmit={search}><span className="search-icon">⌖</span><select aria-label="College" value={filters.collegeId} onChange={e=>setFilters({...filters,collegeId:e.target.value})}><option value="">Where is your college?</option>{colleges.map(c=><option key={c.id} value={c.id}>{c.name} · {c.locality}</option>)}</select><select aria-label="Gender" className="hero-gender" value={filters.gender} onChange={e=>setFilters({...filters,gender:e.target.value})}><option value="">For everyone</option><option value="MALE">Men</option><option value="FEMALE">Women</option><option value="CO_ED">Co-ed</option></select><button aria-label="Search hostels">→</button></form>{selectedCollege&&<Link className="college-page-link" to={`/colleges/${selectedCollege.slug}`}>Explore {selectedCollege.name} hostels →</Link>}</div><div className="hero-student">🎒</div></section>
  <div className="popular-colleges"><b>Popular colleges</b>{colleges.slice(0,4).map(c=><Link key={c.id} to={`/colleges/${c.slug}`}>{c.name}</Link>)}</div></>}
  <section className="results-shell" id="explore"><aside className={`filter-rail ${mobileFilters?'mobile-open':''}`}><div className="filter-title"><h2>Filters</h2><button type="button" onClick={clear}>Clear all</button><button className="filter-close" aria-label="Close filters" onClick={()=>setMobileFilters(false)}>×</button></div><label>GENDER</label><Chips value={filters.gender} onChange={v=>setFilters({...filters,gender:v})}/><label>ROOM TYPE</label><select aria-label="Room type" value={filters.acType} onChange={e=>setFilters({...filters,acType:e.target.value})}><option value="">All room types</option><option value="AC">AC rooms</option><option value="NON_AC">Non-AC rooms</option></select><label>MONTHLY RENT <span className="rent-values">₹{Number(filters.minPrice||0).toLocaleString('en-IN')} – ₹{Number(filters.maxPrice||30000).toLocaleString('en-IN')}</span></label><div className="price-sliders"><input aria-label="Minimum monthly rent" type="range" min="0" max="30000" step="500" value={filters.minPrice||0} onChange={e=>setFilters({...filters,minPrice:e.target.value})}/><input aria-label="Maximum monthly rent" type="range" min="0" max="30000" step="500" value={filters.maxPrice||30000} onChange={e=>setFilters({...filters,maxPrice:e.target.value})}/></div><label className="checkbox"><input type="checkbox" checked={filters.onlyVacant} onChange={e=>setFilters({...filters,onlyVacant:e.target.checked})}/> Only show vacancies</label><label className="checkbox"><input type="checkbox" checked={filters.coLiving===true} onChange={e=>setFilters({...filters,coLiving:e.target.checked?true:''})}/> Co-living</label><button className="apply-filter" onClick={()=>setMobileFilters(false)}>Apply filters</button></aside>
   <section className="listing-area"><div className="listing-heading"><div><p className="eyebrow">EXPLORE STUDENT STAYS</p><h2>{filters.gender==='MALE'?'Boys':filters.gender==='FEMALE'?'Girls':'Student'} hostels {fixedCollegeName?`near ${fixedCollegeName}`:'near your college'}</h2><p>{loading?'Searching…':`${items.length} hostel${items.length===1?'':'s'} found`}</p></div><div className="listing-controls"><button className="mobile-filter-button" onClick={()=>setMobileFilters(true)}>☷ Filters</button><select aria-label="Sort hostels" value={sort} onChange={e=>setSort(e.target.value)}><option value="recommended">Recommended</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="distance">Nearest college</option><option value="vacancies">Most vacancies</option></select></div></div>{selectedCollege&&<p className="active-filter">{selectedCollege.name}{!initialCollegeId&&<button onClick={()=>setFilters({...filters,collegeId:''})}>×</button>}</p>}{error&&<p className="notice error">{error}</p>}<div className="hostel-grid">{loading?<p className="loading">Loading hostels…</p>:sortedItems.length?sortedItems.map(h=><Card hostel={h} college={selectedCollege?.name} key={h.id}/>):<div className="empty"><strong>No hostels match these filters.</strong><p>Try clearing a filter or expanding your price range.</p></div>}</div></section>
  </section>
 </main>
}
function HostelExtras(){const{id}=useParams(),[hostel,setHostel]=useState(null),[error,setError]=useState('');useEffect(()=>{setHostel(null);setError('');api.get(`/hostels/${id}`).then(r=>setHostel(r.data)).catch(e=>setError(problem(e)))},[id]);if(error)return <section className="hostel-extras"><p className="notice error" role="alert">{error}</p></section>;if(!hostel)return <section className="hostel-extras" aria-live="polite">Loading charges…</section>;const show=(v,format=x=>x)=>v==null?'Not specified':format(v);return <section className="hostel-extras"><h2>Charges and policies</h2><div className="policy-grid"><p>Security deposit <b>{show(hostel.securityDeposit,money)}</b></p><p>Maintenance / month <b>{show(hostel.maintenanceChargePerMonth,money)}</b></p><p>Mess / month <b>{show(hostel.messChargePerMonth,money)}</b></p><p>Electricity <b>{show(hostel.electricityPolicy,x=>x==='FIXED'?`Fixed · ${show(hostel.electricityChargePerMonth,money)}/mo`:x.toLowerCase())}</b></p><p>Lock-in <b>{show(hostel.lockInMonths,x=>`${x} months`)}</b></p><p>Notice period <b>{show(hostel.noticePeriodDays,x=>`${x} days`)}</b></p></div><h2>First month cost by room</h2><div className="cost-room-grid">{hostel.rooms.map(room=><article key={room.id}><h3>Room {room.roomNumber}</h3><b>{room.breakdownComplete&&room.firstMonthTotal!=null?`First month total ${money(room.firstMonthTotal)}`:'First month total: Not specified'}</b><details><summary>View cost breakdown</summary>{room.costBreakdown?.map((line,index)=><p key={`${line.label}-${index}`}>{line.label}<span>{money(line.amount)}</span></p>)}{!room.breakdownComplete&&<small>Some charges have not been specified.</small>}</details></article>)}</div></section>}
function ShareActions(){const{id}=useParams(),[hostel,setHostel]=useState(null),[error,setError]=useState(''),[toast,setToast]=useState('');useEffect(()=>{api.get(`/hostels/${id}`).then(r=>setHostel(r.data)).catch(e=>setError(problem(e)))},[id]);if(error)return <section className="hostel-extras"><p className="notice error" role="alert">{error}</p></section>;if(!hostel)return <section className="hostel-extras" aria-live="polite">Loading contact options…</section>;const url=window.location.href,selectedCollege=new URLSearchParams(window.location.search).get('college'),number=(hostel.contactWhatsapp||hostel.contactPhone||'').replace(/\D/g,''),whatsapp=number.length===10?`91${number}`:number,chatText=`Hi, I’m interested in ${hostel.name}${selectedCollege?` near ${selectedCollege}`:''}. Could you share more details? ${url}`,knownTotals=hostel.rooms.map(r=>r.firstMonthTotal).filter(v=>v!=null),firstTotal=knownTotals.length?Math.min(...knownTotals):null,parentText=`${hostel.name} in ${hostel.locality}. Monthly rent from ${hostel.rooms.length?money(Math.min(...hostel.rooms.map(r=>r.pricePerMonth))):'Not specified'}.${firstTotal==null?'':` First-month total from ${money(firstTotal)}.`} ${url}`,chatUrl=`https://wa.me/${whatsapp}?text=${encodeURIComponent(chatText)}`,shareUrl=`https://wa.me/?text=${encodeURIComponent(parentText)}`;const share=async()=>{setToast('');if(navigator.share){try{await navigator.share({title:hostel.name,text:parentText,url});setToast('Share sheet opened.')}catch(e){if(e.name!=='AbortError')setToast('Could not open the share sheet.')}}else{window.open(shareUrl,'_blank','noopener,noreferrer');try{await navigator.clipboard.writeText(url);setToast('WhatsApp opened and link copied.')}catch{setToast('WhatsApp opened. Copy the page URL from your address bar.')}}};const copy=async()=>{try{await navigator.clipboard.writeText(url);setToast('Link copied for sharing.')}catch{setToast('Copy is unavailable. Copy the page URL from your address bar.')}};return <section className="hostel-extras share-actions"><a className="primary-button" href={chatUrl} target="_blank" rel="noopener noreferrer">Chat on WhatsApp</a><button onClick={share}>Share with parents</button>{!navigator.share&&<button className="secondary-button" onClick={copy}>Copy link</button>}{toast&&<p className="notice success" role="status">{toast}</p>}</section>}
function AvailabilityFreshness(){const{id}=useParams(),[rooms,setRooms]=useState(null),[error,setError]=useState('');useEffect(()=>{api.get(`/hostels/${id}`).then(r=>setRooms(r.data.rooms)).catch(e=>setError(problem(e)))},[id]);if(error)return <section className="hostel-extras"><p className="notice error">{error}</p></section>;if(!rooms)return <section className="hostel-extras" aria-live="polite">Loading availability…</section>;const relative=new Intl.RelativeTimeFormat('en',{numeric:'auto'}),format=stamp=>{if(!stamp)return 'Not specified';const seconds=(Date.parse(stamp)-Date.now())/1000;for(const [unit,size] of [['year',31536000],['month',2592000],['week',604800],['day',86400],['hour',3600],['minute',60]])if(Math.abs(seconds)>=size)return relative.format(Math.round(seconds/size),unit);return relative.format(Math.round(seconds),'second')};return <section className="hostel-extras"><h2>Availability freshness</h2>{rooms.length?rooms.map(room=>{const stale=room.availabilityUpdatedAt&&Date.now()-Date.parse(room.availabilityUpdatedAt)>AVAILABILITY_STALE_AFTER_MS;return <div className="public-availability-row" key={room.id}><b>{room.roomNumber}</b><span>Availability updated {format(room.availabilityUpdatedAt)}</span>{stale&&<span className="stale-badge">May be outdated</span>}</div>}):<p className="empty">No rooms listed.</p>}</section>}
function MenuExtras(){const{id}=useParams(),[hostel,setHostel]=useState(null),[error,setError]=useState('');useEffect(()=>{api.get(`/hostels/${id}`).then(r=>setHostel(r.data)).catch(e=>setError(problem(e)))},[id]);if(error)return <section className="hostel-extras"><p className="notice error">{error}</p></section>;if(!hostel)return <section className="hostel-extras" aria-live="polite">Loading food information…</section>;const type=hostel.foodType;return <section className="hostel-extras"><h2>Food and mess</h2><div className="food-badges">{type&&type!=='NONE'&&<span>{type==='BOTH'?'Veg and non-veg':type==='VEG'?'Veg':'Non-veg'}</span>}{hostel.messIncludedInRent===true&&<span>Food included</span>}{hostel.messIncludedInRent===false&&<span>Mess paid separately</span>}{!type&&<span>Food type: Not specified</span>}</div><p>Meal timings: {hostel.mealTimings||'Not specified'}</p>{hostel.weeklyMenu?.length?<div className="menu-table-wrap"><table className="menu-table"><thead><tr><th>Day</th><th>Breakfast</th><th>Lunch</th><th>Snacks</th><th>Dinner</th></tr></thead><tbody>{hostel.weeklyMenu.map(day=><tr key={day.dayOfWeek}><th>{day.dayOfWeek[0]+day.dayOfWeek.slice(1).toLowerCase()}</th><td>{day.breakfast||'Not specified'}</td><td>{day.lunch||'Not specified'}</td><td>{day.snacks||'Not specified'}</td><td>{day.dinner||'Not specified'}</td></tr>)}</tbody></table></div>:<p className="empty">No weekly menu has been provided.</p>}</section>}
function CollegePage(){const{slug}=useParams(),[college,setCollege]=useState(null),[error,setError]=useState('');useEffect(()=>{setCollege(null);setError('');api.get(`/colleges/${slug}`).then(r=>setCollege(r.data)).catch(e=>setError(e?.response?.status===404?'not-found':problem(e)))},[slug]);if(error==='not-found')return <NotFound/>;if(error)return <main className="page-space"><p className="notice error" role="alert">{error}</p><Link to="/">Return to search</Link></main>;if(!college)return <main className="page-space" aria-live="polite">Loading college…</main>;return <><section className="college-landing"><p className="eyebrow">STUDENT STAYS NEAR</p><h1>{college.name}</h1><p>{college.locality}, {college.city}</p><div className="college-stats"><article><b>{college.hostelCount}</b><span>Hostels</span></article><article><b>{college.vacantBeds}</b><span>Vacant beds</span></article><article><b>{college.minPricePerMonth==null?'Not specified':money(college.minPricePerMonth)}</b><span>From per month</span></article><article><b>{college.avgPricePerMonth==null?'Not specified':money(college.avgPricePerMonth)}</b><span>Average per month</span></article></div></section><Home initialCollegeId={String(college.id)} fixedCollegeName={college.name}/></>}
function Booking({room,onClose}){const [form,setForm]=useState({}),[message,setMessage]=useState(''),[error,setError]=useState('');const submit=async e=>{e.preventDefault();try{const r=await api.post(`/rooms/${room.id}/booking-requests`,form);setMessage(r.data.message)}catch(e){setError(problem(e))}};return <div className="modal"><form className="dialog" onSubmit={submit}><button type="button" className="close" aria-label="Close booking form" onClick={onClose}>×</button><p className="eyebrow">ROOM {room.roomNumber}</p><h2>Request this room</h2>{message?<p className="notice success" role="status">{message}</p>:<>{[['studentName','Your full name','text'],['phone','Phone number','tel'],['email','Email address','email'],['moveInDate','Move-in date','date']].map(([key,placeholder,type])=><input key={key} required aria-label={placeholder} type={type} placeholder={placeholder} onChange={e=>setForm({...form,[key]:e.target.value})}/>)}{error&&<p className="notice error" role="alert">{error}</p>}<button>Send request →</button></>}</form></div>}
function Details(){const{id}=useParams(),[hostel,setHostel]=useState(),[room,setRoom]=useState(),[error,setError]=useState('');useEffect(()=>{api.get(`/hostels/${id}`).then(r=>setHostel(r.data)).catch(e=>setError(problem(e)))},[id]);if(error)return <main className="page-space"><p className="notice error">{error}</p><Link className="back" to="/">← All hostels</Link></main>;if(!hostel)return <main className="page-space">Loading hostel…</main>;const photos=hostel.imageUrls?.length?hostel.imageUrls:[fallback];const firstRoom=hostel.rooms.find(r=>r.vacantBeds>0);return <main className="detail-page"><Link className="back" to="/">← All hostels</Link><section className="photo-gallery">{photos.slice(0,3).map((photo,index)=><img key={photo+index} className={index===0?'gallery-main':`gallery-side gallery-side-${index}`} src={photo} alt={`${hostel.name} photo ${index+1}`} onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=fallback}}/>)}<div className="gallery-heading"><span className="light-pill">{hostel.genderType.replace('_',' ')}</span><h1>{hostel.name}</h1><p>{hostel.locality}, {hostel.city}</p></div></section><section className="detail-layout"><div><h2>Overview</h2><p>{hostel.description}</p><h2>Amenities</h2><div className="amenities">{hostel.amenities.map(a=><span key={a}>✓ {a}</span>)}</div><h2>Location</h2><MapContainer center={[hostel.latitude,hostel.longitude]} zoom={15}><TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/><Marker position={[hostel.latitude,hostel.longitude]}/></MapContainer><h2>House rules</h2><p>{hostel.rules}</p></div><aside className="contact-card sticky-booking"><p className="eyebrow">ROOMS FROM</p><h3>{money(Math.min(...hostel.rooms.map(r=>r.pricePerMonth)))}</h3><p>per month · {hostel.rooms.reduce((n,r)=>n+r.vacantBeds,0)} beds available</p>{firstRoom&&<button onClick={()=>setRoom(firstRoom)}>Request booking →</button>}<hr/><p className="eyebrow">HOSTEL MANAGER</p><b>{hostel.contactName}</b><a className="contact-call" href={`tel:${hostel.contactPhone}`}>☎ Call {hostel.contactPhone}</a><a href={`mailto:${hostel.contactEmail}`}>✉ {hostel.contactEmail}</a></aside></section><h2 className="room-title">Rooms and availability</h2><div className="room-list">{hostel.rooms.map(r=><article key={r.id} className="room room-detail"><div><b>{r.roomNumber}</b><span>{r.acType.replace('_',' ')} · {r.occupied}/{r.capacity} occupied</span><span className="vacancy-track"><i style={{width:`${Math.max(0,Math.min(100,(r.vacantBeds/r.capacity)*100))}%`}}/></span>{r.description&&<p>{r.description}</p>}{r.amenities&&<div className="room-amenities">{r.amenities.split(',').map(a=><span key={a}>{a.trim()}</span>)}</div>}</div><div><b>{money(r.pricePerMonth)}<small>/month</small></b><span>{r.vacantBeds} beds available</span><span>{money(r.pricePerDay)} / day</span></div>{r.vacantBeds?<button onClick={()=>setRoom(r)}>Request room</button>:<span className="sold">Full</span>}{r.imageUrls?.length>0&&<div className="room-photos">{r.imageUrls.map((src,i)=><img key={`${src}-${i}`} src={src} alt={`${r.roomNumber} room photo ${i+1}`} loading="lazy" onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=fallback}}/>)}</div>}</article>)}</div>{room&&<Booking room={room} onClose={()=>setRoom(null)}/>}</main>}
function Login(){const nav=useNavigate(),{signIn}=useAuth(),[register,setRegister]=useState(false),[form,setForm]=useState({}),[error,setError]=useState(''),[busy,setBusy]=useState(false);const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{const r=await api.post(`/auth/${register?'register':'login'}`,form);signIn(r.data);nav('/manager')}catch(e){setError(problem(e))}finally{setBusy(false)}};return <main className="auth-page"><section className="auth-aside"><Logo/><div><p className="eyebrow">FOR HOSTEL MANAGERS</p><h1>Grow your student community.</h1><p>Create your listing, control room availability, and review every booking request in one place.</p></div></section><section className="auth-card"><p className="eyebrow">MANAGER ACCESS</p><h1>{register?'Create your account':'Welcome back'}</h1><p>{register?'List your hostel in a few minutes.':'Sign in to manage your hostel listings.'}</p><form onSubmit={submit}>{register&&<><input required placeholder="Full name" onChange={e=>setForm({...form,name:e.target.value})}/><input required placeholder="Phone number" onChange={e=>setForm({...form,phone:e.target.value})}/></>}<input required type="email" placeholder="Email address" onChange={e=>setForm({...form,email:e.target.value})}/><input required minLength="6" type="password" placeholder="Password" onChange={e=>setForm({...form,password:e.target.value})}/>{error&&<p className="notice error" role="alert">{error}</p>}<button disabled={busy}>{busy?'Please wait…':register?'Create account':'Sign in →'}</button></form>{!register&&<p className="seed-note">Demo: manager1@hosteldekho.com / Manager@123</p>}<button type="button" className="text-button" onClick={()=>{setRegister(!register);setError('')}}>{register?'Already registered? Sign in':'New manager? Create an account'}</button></section></main>}
function Protected({children}){const {isAuthenticated}=useAuth();return isAuthenticated?children:<Navigate to="/login" replace/>}
function Dashboard(){const [hostels,setHostels]=useState([]),[bookings,setBookings]=useState([]),[error,setError]=useState(''),{manager}=useAuth();const load=async()=>{try{const [listingData,requestData]=await Promise.all([api.get('/manager/hostels'),api.get('/manager/booking-requests')]);setHostels(listingData.data);setBookings(requestData.data)}catch(e){setError(problem(e))}};useEffect(()=>{load()},[]);const remove=async id=>{if(!window.confirm('Delete this hostel and all its rooms?'))return;try{await api.delete(`/manager/hostels/${id}`);await load()}catch(e){setError(problem(e))}};const totalBeds=hostels.reduce((n,h)=>n+h.rooms.reduce((sum,r)=>sum+r.capacity,0),0),vacantBeds=hostels.reduce((n,h)=>n+h.rooms.reduce((sum,r)=>sum+r.vacantBeds,0),0),pending=bookings.filter(x=>x.status==='PENDING').length;return <main className="manager-page"><div className="manager-top"><div><p className="eyebrow">MANAGER DASHBOARD</p><h1>Hello, {manager?.name}</h1></div><Link className="primary-button" to="/manager/hostels/new">+ Add hostel</Link></div>{error&&<p className="notice error" role="alert">{error}</p>}<div className="stats-grid"><article><b>{hostels.length}</b><span>Hostels listed</span></article><article><b>{totalBeds}</b><span>Total beds</span></article><article><b>{vacantBeds}</b><span>Vacant beds</span></article><article><b>{pending}</b><span>Pending requests</span></article></div><div className="manager-actions"><h2>Your hostels</h2><Link to="/manager/requests">Booking requests →</Link></div><div className="hostel-grid">{hostels.map(h=><article className="hostel-card manager-card" key={h.id}><img src={h.imageUrls?.[0]||fallback} alt={h.name} onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=fallback}}/><div className="card-body"><h2>{h.name}</h2><p>{h.rooms.length} rooms · {h.locality}</p><Link to={`/manager/hostels/${h.id}`}>Edit listing</Link><Link to={`/manager/hostels/${h.id}/rooms`}>Manage rooms</Link><button className="delete-link" onClick={()=>remove(h.id)}>Delete hostel</button></div></article>)}</div>{!hostels.length&&!error&&<div className="empty">No hostels listed yet. Add your first property.</div>}</main>}
function Picker({value,onChange}){function Click(){useMapEvents({click:e=>onChange(e.latlng)});return null}const pos=[value.latitude||17.728,value.longitude||83.321];return <MapContainer center={pos} zoom={13}><TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/><Click/>{value.latitude&&<Marker position={pos}/>}</MapContainer>}
function HostelSettings(){const{id}=useParams(),[hostel,setHostel]=useState(null),[values,setValues]=useState({}),[error,setError]=useState(''),[saved,setSaved]=useState(false);useEffect(()=>{api.get('/manager/hostels').then(r=>{const h=r.data.find(x=>x.id===Number(id));if(!h){setError('Hostel not found');return}setHostel(h);setValues({securityDeposit:h.securityDeposit??'',maintenanceChargePerMonth:h.maintenanceChargePerMonth??'',messChargePerMonth:h.messChargePerMonth??'',electricityPolicy:h.electricityPolicy??'',electricityChargePerMonth:h.electricityChargePerMonth??'',lockInMonths:h.lockInMonths??'',noticePeriodDays:h.noticePeriodDays??'',messIncludedInRent:h.messIncludedInRent??''})}).catch(e=>setError(problem(e)))},[id]);const set=(key,value)=>{setSaved(false);setValues(current=>({...current,[key]:value}))};const submit=async e=>{e.preventDefault();setError('');try{const nullable=(v)=>v===''?null:Number(v);const body={name:hostel.name,description:hostel.description,address:hostel.address,locality:hostel.locality,city:hostel.city,latitude:hostel.latitude,longitude:hostel.longitude,genderType:hostel.genderType,coLiving:hostel.coLiving,contactName:hostel.contactName,contactPhone:hostel.contactPhone,contactEmail:hostel.contactEmail,rules:hostel.rules,amenities:hostel.amenities.join(', '),imageUrls:hostel.imageUrls,colleges:hostel.colleges,...values,securityDeposit:nullable(values.securityDeposit),maintenanceChargePerMonth:nullable(values.maintenanceChargePerMonth),messChargePerMonth:nullable(values.messChargePerMonth),electricityChargePerMonth:nullable(values.electricityChargePerMonth),lockInMonths:nullable(values.lockInMonths),noticePeriodDays:nullable(values.noticePeriodDays),messIncludedInRent:values.messIncludedInRent===''?null:values.messIncludedInRent==='true'};await api.put(`/manager/hostels/${id}`,body);setSaved(true)}catch(e){setError(problem(e))}};if(error&&!hostel)return <section className="manager-settings"><p className="notice error">{error}</p></section>;if(!hostel)return <section className="manager-settings" aria-live="polite">Loading charges…</section>;return <section className="manager-settings"><h2>Charges and policies</h2><p>Leave an amount blank when it has not been specified.</p><form onSubmit={submit}><div className="form-fields">{[['securityDeposit','Security deposit (₹)'],['maintenanceChargePerMonth','Maintenance per month (₹)'],['messChargePerMonth','Mess per month (₹)'],['lockInMonths','Lock-in (months)'],['noticePeriodDays','Notice period (days)']].map(([key,label])=><label key={key}>{label}<input type="number" min="0" value={values[key]} placeholder="Not specified" onChange={e=>set(key,e.target.value)}/></label>)}<label>Electricity policy<select value={values.electricityPolicy} onChange={e=>set('electricityPolicy',e.target.value)}><option value="">Not specified</option><option value="INCLUDED">Included</option><option value="FIXED">Fixed monthly</option><option value="METERED">Metered</option></select></label><label>Fixed electricity per month (₹)<input type="number" min="0" value={values.electricityChargePerMonth} placeholder="Not specified" onChange={e=>set('electricityChargePerMonth',e.target.value)}/></label><label>Mess included in rent<select value={values.messIncludedInRent} onChange={e=>set('messIncludedInRent',e.target.value)}><option value="">Not specified</option><option value="true">Yes</option><option value="false">No</option></select></label></div>{error&&<p className="notice error" role="alert">{error}</p>}{saved&&<p className="notice success" role="status">Charges saved.</p>}<button>Save charges</button></form></section>}
function HostelForm(){const{id}=useParams(),nav=useNavigate(),[colleges,setColleges]=useState([]),[form,setForm]=useState({genderType:'MALE',coLiving:false,latitude:17.728,longitude:83.321,colleges:[],imageUrls:''}),[error,setError]=useState('');useEffect(()=>{api.get('/colleges').then(r=>setColleges(r.data)).catch(e=>setError(problem(e)));if(id)api.get('/manager/hostels').then(r=>{const h=r.data.find(x=>x.id===Number(id));if(h)setForm({...h,amenities:h.amenities.join(', '),imageUrls:h.imageUrls.join(', ')})}).catch(e=>setError(problem(e)))},[id]);const set=(key,value)=>setForm({...form,[key]:value});const selectCollege=c=>set('colleges',form.colleges.some(x=>x.collegeId===c.id)?form.colleges.filter(x=>x.collegeId!==c.id):[...form.colleges,{collegeId:c.id,distanceKm:1}]);const submit=async e=>{e.preventDefault();try{const body={...form,latitude:+form.latitude,longitude:+form.longitude,imageUrls:form.imageUrls.split(',').map(url=>url.trim()).filter(Boolean)};id?await api.put(`/manager/hostels/${id}`,body):await api.post('/manager/hostels',body);nav('/manager')}catch(e){setError(problem(e))}};return <main className="form-page"><Link className="back" to="/manager">← Dashboard</Link><h1>{id?'Edit hostel':'Add your hostel'}</h1><form className="listing-form" onSubmit={submit}><div className="form-fields">{[['name','Hostel name'],['description','Short description'],['address','Full address'],['locality','Locality'],['city','City'],['contactName','Contact person'],['contactPhone','Phone number'],['contactEmail','Email address'],['rules','House rules'],['amenities','Amenities (comma separated)'],['imageUrls','Image URLs (comma separated)']].map(([key,label])=><label key={key}>{label}<input aria-label={label} required={!['description','rules','amenities','imageUrls'].includes(key)} value={form[key]||''} onChange={e=>set(key,e.target.value)}/></label>)}<label>Gender<select value={form.genderType} onChange={e=>set('genderType',e.target.value)}><option value="MALE">Male</option><option value="FEMALE">Female</option><option value="CO_ED">Co-ed</option></select></label><label className="checkbox"><input type="checkbox" checked={form.coLiving} onChange={e=>set('coLiving',e.target.checked)}/> Co-living property</label></div><div className="college-box"><h3>Nearby colleges</h3>{colleges.map(c=>{const link=form.colleges.find(x=>x.collegeId===c.id);return <label key={c.id} className="college-option"><input type="checkbox" checked={Boolean(link)} onChange={()=>selectCollege(c)}/>{c.name}{link&&<input aria-label={`${c.name} distance in kilometers`} type="number" min="0" step="0.1" value={link.distanceKm} onChange={e=>set('colleges',form.colleges.map(x=>x.collegeId===c.id?{...x,distanceKm:+e.target.value}:x))}/>}</label>})}<h3>Pin your location</h3><Picker value={form} onChange={point=>setForm({...form,latitude:point.lat,longitude:point.lng})}/><small>{form.latitude}, {form.longitude}</small></div>{error&&<p className="notice error" role="alert">{error}</p>}<button>Save hostel →</button></form></main>}
function WhatsappSettings(){const{id}=useParams(),[hostel,setHostel]=useState(null),[number,setNumber]=useState(''),[error,setError]=useState(''),[saved,setSaved]=useState(false);useEffect(()=>{api.get('/manager/hostels').then(r=>{const h=r.data.find(x=>x.id===Number(id));setHostel(h||null);setNumber(h?.contactWhatsapp||'')}).catch(e=>setError(problem(e)))},[id]);const submit=async e=>{e.preventDefault();setError('');try{await api.put(`/manager/hostels/${id}`,{name:hostel.name,description:hostel.description,address:hostel.address,locality:hostel.locality,city:hostel.city,latitude:hostel.latitude,longitude:hostel.longitude,genderType:hostel.genderType,coLiving:hostel.coLiving,contactName:hostel.contactName,contactPhone:hostel.contactPhone,contactWhatsapp:number,contactEmail:hostel.contactEmail,rules:hostel.rules,amenities:hostel.amenities.join(', '),imageUrls:hostel.imageUrls,colleges:hostel.colleges,securityDeposit:hostel.securityDeposit,maintenanceChargePerMonth:hostel.maintenanceChargePerMonth,messChargePerMonth:hostel.messChargePerMonth,electricityPolicy:hostel.electricityPolicy,electricityChargePerMonth:hostel.electricityChargePerMonth,lockInMonths:hostel.lockInMonths,noticePeriodDays:hostel.noticePeriodDays,messIncludedInRent:hostel.messIncludedInRent,foodType:hostel.foodType,mealTimings:hostel.mealTimings,weeklyMenu:hostel.weeklyMenu});setSaved(true)}catch(e){setError(problem(e))}};if(error&&!hostel)return <section className="manager-settings"><p className="notice error">{error}</p></section>;if(!hostel)return <section className="manager-settings" aria-live="polite">Loading contact details…</section>;return <section className="manager-settings"><h2>WhatsApp contact</h2><form onSubmit={submit}><label>WhatsApp number (optional)<input type="tel" value={number} placeholder="Falls back to phone number" onChange={e=>{setNumber(e.target.value);setSaved(false)}}/></label>{error&&<p className="notice error" role="alert">{error}</p>}{saved&&<p className="notice success" role="status">WhatsApp contact saved.</p>}<button>Save contact</button></form></section>}
function AvailabilityManager(){const{id}=useParams(),[hostel,setHostel]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState('');const load=()=>api.get('/manager/hostels').then(r=>setHostel(r.data.find(h=>h.id===Number(id))||null)).catch(e=>setError(problem(e)));useEffect(()=>{load()},[id]);const step=async(room,delta)=>{setBusy(true);setError('');setMessage('');try{await api.post(`/manager/rooms/${room.id}/occupancy`,{delta});await load()}catch(e){setError(problem(e))}finally{setBusy(false)}};const confirm=async()=>{setBusy(true);setError('');try{await api.post(`/manager/hostels/${id}/rooms/confirm-availability`);await load();setMessage('Room availability confirmed.')}catch(e){setError(problem(e))}finally{setBusy(false)}};if(error&&!hostel)return <section className="manager-settings"><p className="notice error">{error}</p></section>;if(!hostel)return <section className="manager-settings" aria-live="polite">Loading availability…</section>;return <section className="manager-settings"><div className="menu-editor-heading"><div><h2>Availability freshness</h2><p>Update occupancy one bed at a time or confirm all current counts.</p></div><button disabled={busy} onClick={confirm}>Confirm all rooms are up to date</button></div>{error&&<p className="notice error" role="alert">{error}</p>}{message&&<p className="notice success" role="status">{message}</p>}{hostel.rooms.length===0?<p className="empty">No rooms have been added yet.</p>:hostel.rooms.map(room=><div className="availability-manager-row" key={room.id}><b>{room.roomNumber}</b><span>{room.occupied} / {room.capacity} occupied</span><button disabled={busy||room.occupied<=0} aria-label={`Decrease ${room.roomNumber} occupancy`} onClick={()=>step(room,-1)}>−</button><button disabled={busy||room.occupied>=room.capacity} aria-label={`Increase ${room.roomNumber} occupancy`} onClick={()=>step(room,1)}>+</button></div>)}</section>}
function Rooms(){
 const{id}=useParams(),[hostel,setHostel]=useState(),[form,setForm]=useState(),[error,setError]=useState('');
 const load=()=>api.get('/manager/hostels').then(r=>setHostel(r.data.find(x=>x.id===Number(id)))).catch(e=>setError(problem(e)));
 useEffect(()=>{load()},[id]);
 const edit=room=>setForm({...room,amenities:room.amenities||'',imageUrls:room.imageUrls||[],imageUrlInput:''});
 const addFiles=async event=>{const files=Array.from(event.target.files||[]);event.target.value='';if((form.imageUrls||[]).length+files.length>4){setError('Add up to four room photos.');return}try{const images=await Promise.all(files.map(imageFileToDataUrl));setForm(current=>({...current,imageUrls:[...(current.imageUrls||[]),...images]}));setError('')}catch(e){setError(e.message)}};
 const save=async e=>{e.preventDefault();const links=(form.imageUrlInput||'').split(/\r?\n/).map(url=>url.trim()).filter(Boolean);const imageUrls=[...(form.imageUrls||[]),...links];if(imageUrls.length>4){setError('Add up to four room photos.');return}try{const payload={...form,imageUrls};delete payload.imageUrlInput;form.id?await api.put(`/manager/hostels/${id}/rooms/${form.id}`,payload):await api.post(`/manager/hostels/${id}/rooms`,payload);setForm(null);setError('');load()}catch(e){setError(problem(e))}};
 const remove=async room=>{if(!window.confirm(`Delete room ${room.roomNumber}?`))return;try{await api.delete(`/manager/hostels/${id}/rooms/${room.id}`);load()}catch(e){setError(problem(e))}};
 if(!hostel)return <main className="page-space">Loading rooms…</main>;
 const startRoom=()=>{setError('');setForm({roomNumber:'',acType:'NON_AC',capacity:2,occupied:0,pricePerMonth:8000,pricePerDay:400,description:'',amenities:'',imageUrls:[],imageUrlInput:''})};
 return <main className="manager-page"><Link className="back" to="/manager">← Dashboard</Link><h1>Rooms at {hostel.name}</h1><button className="primary-button" onClick={startRoom}>+ Add room</button>
  {form&&<form className="room-form" onSubmit={save}>
   <input required aria-label="Room number" placeholder="Room number" value={form.roomNumber} onChange={e=>setForm({...form,roomNumber:e.target.value})}/>
   <select aria-label="AC type" value={form.acType} onChange={e=>setForm({...form,acType:e.target.value})}><option value="AC">AC</option><option value="NON_AC">Non-AC</option></select>
   {['capacity','occupied','pricePerMonth','pricePerDay'].map(key=><input key={key} aria-label={key} required type="number" min={key==='occupied'?0:1} value={form[key]} onChange={e=>setForm({...form,[key]:+e.target.value})}/>)}
   <label className="room-wide-field">Room information<textarea aria-label="Room information" placeholder="Describe the room" value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></label>
   <label className="room-wide-field">Room amenities (comma separated)<input aria-label="Room amenities" placeholder="Attached bath, wardrobe, balcony" value={form.amenities||''} onChange={e=>setForm({...form,amenities:e.target.value})}/></label>
   <label className="room-wide-field">Upload room photos<input aria-label="Upload room photos" type="file" accept="image/*" multiple onChange={addFiles}/><small>Choose up to four images. Photos are resized before saving.</small></label>
   <label className="room-wide-field">Or paste image URLs (one per line)<textarea aria-label="Room photo URLs" placeholder="https://example.com/room-1.jpg" value={form.imageUrlInput||''} onChange={e=>setForm({...form,imageUrlInput:e.target.value})}/></label>
   {[...(form.imageUrls||[]),...(form.imageUrlInput||'').split(/\r?\n/).map(url=>url.trim()).filter(Boolean)].map((url,i)=><img className="room-form-preview" key={`${url.slice(0,60)}-${i}`} src={url} alt={`Room preview ${i+1}`} onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=fallback}}/>)}
   <button>Save room</button><button type="button" className="secondary-button" onClick={()=>setForm(null)}>Cancel</button>
  </form>}
  {error&&<p className="notice error" role="alert">{error}</p>}
  <div className="room-list">{hostel.rooms.map(r=><article className="room" key={r.id}><div><b>{r.roomNumber}</b><span>{r.acType} · {r.occupied}/{r.capacity} occupied · {r.vacantBeds} vacant</span>{r.description&&<p>{r.description}</p>}{r.imageUrls?.length>0&&<div className="room-photos">{r.imageUrls.map((src,i)=><img key={`${src.slice(0,60)}-${i}`} src={src} alt={`${r.roomNumber} room photo ${i+1}`} loading="lazy" onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src=fallback}}/>)}</div>}</div><b>{money(r.pricePerMonth)}</b><button onClick={()=>edit(r)}>Edit</button><button className="delete-link" onClick={()=>remove(r)}>Delete</button></article>)}</div>
 </main>
}
function Requests(){const [items,setItems]=useState([]),[error,setError]=useState(''),[tab,setTab]=useState('PENDING');const load=()=>api.get('/manager/booking-requests').then(r=>setItems(r.data)).catch(e=>setError(problem(e)));useEffect(()=>{load()},[]);const change=async(id,status)=>{const action=status==='approve'?'approve':'reject';if(!window.confirm(`Are you sure you want to ${action} this booking request?`))return;try{await api.put(`/manager/booking-requests/${id}/${status}`);load()}catch(e){setError(problem(e))}};const shown=items.filter(item=>tab==='ALL'||item.status===tab);return <main className="manager-page"><Link className="back" to="/manager">← Dashboard</Link><h1>Booking requests</h1>{error&&<p className="notice error" role="alert">{error}</p>}<div className="request-tabs">{['PENDING','APPROVED','REJECTED','ALL'].map(value=><button className={tab===value?'active':''} key={value} onClick={()=>setTab(value)}>{value==='ALL'?'All':value[0]+value.slice(1).toLowerCase()} <small>{value==='ALL'?items.length:items.filter(x=>x.status===value).length}</small></button>)}</div><div className="request-list">{shown.map(item=><article key={item.id}><div><b>{item.studentName}</b><span>{item.hostelName} · {item.roomNumber}</span><small>{item.phone} · {item.email} · Move-in {item.moveInDate}</small></div><span className={`status ${item.status.toLowerCase()}`}>{item.status}</span>{item.status==='PENDING'&&<div><button onClick={()=>change(item.id,'approve')}>Approve</button><button className="danger" onClick={()=>change(item.id,'reject')}>Reject</button></div>}</article>)}</div>{!shown.length&&<div className="empty">No {tab.toLowerCase()} requests to show.</div>}</main>}
function NotFound(){return <main className="empty"><h1>Page not found</h1><p>That page isn’t here. Return to the hostel search.</p><Link className="primary-button" to="/">Explore hostels</Link></main>}
function FoodMenuManager(){const{id}=useParams(),days=['MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY'],[hostel,setHostel]=useState(null),[form,setForm]=useState({}),[menu,setMenu]=useState([]),[error,setError]=useState(''),[saved,setSaved]=useState(false);useEffect(()=>{api.get('/manager/hostels').then(r=>{const h=r.data.find(x=>x.id===Number(id));if(!h){setError('Hostel not found');return}setHostel(h);setForm({foodType:h.foodType||'',messIncludedInRent:h.messIncludedInRent==null?'':String(h.messIncludedInRent),mealTimings:h.mealTimings||''});const savedMenu=Object.fromEntries((h.weeklyMenu||[]).map(x=>[x.dayOfWeek,x]));setMenu(days.map(day=>({dayOfWeek:day,breakfast:savedMenu[day]?.breakfast||'',lunch:savedMenu[day]?.lunch||'',snacks:savedMenu[day]?.snacks||'',dinner:savedMenu[day]?.dinner||''}))) }).catch(e=>setError(problem(e)))},[id]);const field=(index,key,value)=>setMenu(current=>current.map((row,i)=>i===index?{...row,[key]:value}:row));const submit=async e=>{e.preventDefault();setError('');try{const body={name:hostel.name,description:hostel.description,address:hostel.address,locality:hostel.locality,city:hostel.city,latitude:hostel.latitude,longitude:hostel.longitude,genderType:hostel.genderType,coLiving:hostel.coLiving,contactName:hostel.contactName,contactPhone:hostel.contactPhone,contactEmail:hostel.contactEmail,rules:hostel.rules,amenities:hostel.amenities.join(', '),imageUrls:hostel.imageUrls,colleges:hostel.colleges,securityDeposit:hostel.securityDeposit,maintenanceChargePerMonth:hostel.maintenanceChargePerMonth,messChargePerMonth:hostel.messChargePerMonth,electricityPolicy:hostel.electricityPolicy,electricityChargePerMonth:hostel.electricityChargePerMonth,lockInMonths:hostel.lockInMonths,noticePeriodDays:hostel.noticePeriodDays,messIncludedInRent:form.messIncludedInRent===''?null:form.messIncludedInRent==='true',foodType:form.foodType||null,mealTimings:form.mealTimings||null,weeklyMenu:menu};await api.put(`/manager/hostels/${id}`,body);setSaved(true)}catch(e){setError(problem(e))}};if(error&&!hostel)return <section className="manager-settings"><p className="notice error">{error}</p></section>;if(!hostel)return <section className="manager-settings" aria-live="polite">Loading food menu…</section>;return <section className="manager-settings"><h2>Food and weekly menu</h2><form onSubmit={submit}><div className="form-fields"><label>Food type<select value={form.foodType} onChange={e=>setForm({...form,foodType:e.target.value})}><option value="">Not specified</option><option value="NONE">No food service</option><option value="VEG">Veg</option><option value="NON_VEG">Non-veg</option><option value="BOTH">Veg and non-veg</option></select></label><label>Food included in rent<select value={form.messIncludedInRent} onChange={e=>setForm({...form,messIncludedInRent:e.target.value})}><option value="">Not specified</option><option value="true">Yes</option><option value="false">No</option></select></label><label className="menu-wide">Meal timings<input value={form.mealTimings} placeholder="Not specified" onChange={e=>setForm({...form,mealTimings:e.target.value})}/></label></div><div className="menu-editor-heading"><h3>Weekly menu</h3><button type="button" className="secondary-button" onClick={()=>setMenu(current=>current.map((row,i)=>i===0?row:{...row,breakfast:current[0].breakfast,lunch:current[0].lunch,snacks:current[0].snacks,dinner:current[0].dinner}))}>Copy Monday to all days</button></div><div className="menu-editor">{menu.map((day,index)=><fieldset key={day.dayOfWeek}><legend>{day.dayOfWeek[0]+day.dayOfWeek.slice(1).toLowerCase()}</legend>{['breakfast','lunch','snacks','dinner'].map(key=><label key={key}>{key[0].toUpperCase()+key.slice(1)}<input value={day[key]} onChange={e=>field(index,key,e.target.value)}/></label>)}</fieldset>)}</div>{error&&<p className="notice error" role="alert">{error}</p>}{saved&&<p className="notice success" role="status">Menu saved.</p>}<button>Save food details</button></form></section>}
function App(){return <AuthProvider><BrowserRouter><Nav/><Routes><Route path="/" element={<><CollegeAutocomplete/><FoodSearchControls/><Home/></>}/><Route path="/colleges/:slug" element={<><FoodSearchControls/><CollegePage/></>}/><Route path="/hostels/:id" element={<><Details/><HostelExtras/><MenuExtras/><AvailabilityFreshness/><ShareActions/></>}/><Route path="/login" element={<Login/>}/><Route path="/manager" element={<Protected><Dashboard/></Protected>}/><Route path="/manager/hostels/new" element={<Protected><HostelForm/></Protected>}/><Route path="/manager/hostels/:id" element={<Protected><><HostelForm/><HostelSettings/><FoodMenuManager/><WhatsappSettings/></></Protected>}/><Route path="/manager/hostels/:id/rooms" element={<Protected><><Rooms/><AvailabilityManager/></></Protected>}/><Route path="/manager/requests" element={<Protected><Requests/></Protected>}/><Route path="*" element={<NotFound/>}/></Routes><Footer/></BrowserRouter></AuthProvider>}
createRoot(document.getElementById('root')).render(<App/>);
